async function pharmacyReturns(root){
 const [ret,sret,pay,sup,disp,inv,po,branches]=await Promise.all([api('/pharmacy/returns'),api('/pharmacy/supplier-returns'),api('/pharmacy/supplier-payments'),api('/pharmacy/suppliers'),api('/pharmacy/dispensings'),api('/pharmacy/inventory'),api('/pharmacy/purchase-orders'),api('/pharmacy/branches')]);
 root.innerHTML=`${pageHeader('Returns & supplier payments','Process assessed customer returns, supplier returns and purchase settlement.',`<div class="flex flex-wrap gap-2"><button id="ph-customer-return" class="btn-secondary">Customer return</button><button id="ph-supplier-return" class="btn-secondary">Supplier return</button><button id="ph-supplier-payment" class="btn-primary">Supplier payment</button></div>`)}
 <section class="card mb-4"><div class="p-4 font-bold text-sm">Customer returns</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Return</th><th>Patient</th><th>Source invoice</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${ret.data.map(x=>`<tr><td>${esc(x.returnNo)}</td><td>${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}</td><td>${esc(x.invoiceId?.invoiceNo||'—')}</td><td>${esc(x.reason)}</td><td>${esc(x.status)}</td><td>${x.status==='pending'&&pharmacyCan('pharmacy.stock.adjust.approve')?`<button class="btn-secondary" data-ret-review="${x._id}">Review</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">No customer returns.</td></tr>'}</tbody></table></div></section>
 <section class="card mb-4"><div class="p-4 font-bold text-sm">Supplier returns</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Return</th><th>Supplier</th><th>Items</th><th>Status</th><th></th></tr></thead><tbody>${sret.data.map(x=>`<tr><td>${esc(x.returnNo)}</td><td>${esc(x.supplierId?.name)}</td><td>${x.items.length}</td><td>${esc(x.status)}</td><td>${x.status==='pending'&&pharmacyCan('pharmacy.purchase.approve')?`<button class="btn-secondary" data-sret-process="${x._id}">Approve & process</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No supplier returns.</td></tr>'}</tbody></table></div></section>
 <section class="card"><div class="p-4 font-bold text-sm">Supplier payments</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Supplier</th><th>Purchase order</th><th>Amount</th><th>Method</th><th>Reference</th></tr></thead><tbody>${pay.data.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString()}</td><td>${esc(x.supplierId?.name)}</td><td>${esc(x.purchaseOrderId?.orderNo||'General')}</td><td>${pharmacyMoney(x.amount)}</td><td>${esc(x.method)}</td><td>${esc(x.reference||'—')}</td></tr>`).join('')||'<tr><td colspan="6">No supplier payments.</td></tr>'}</tbody></table></div></section>`;
 $('#ph-customer-return').onclick=()=>{
  if(!disp.data.length)return toast('No completed dispensing records are available.','error');
  showModal('Request customer return',`<form id="ph-ret-form" class="space-y-3"><label class="field-label">Original dispensing</label><select class="field" name="dispensingId">${disp.data.map(x=>`<option value="${x._id}">${esc(x.dispensingNo)} · ${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}</option>`).join('')}</select><label class="field-label">Return batch</label><select class="field" name="batchId">${disp.data.flatMap(x=>x.items.flatMap(i=>i.batchAllocations.map(b=>`<option value="${b.batchId}" data-disp="${x._id}" data-patient="${x.patientId?._id||''}">${esc(i.medicineName)} · ${esc(b.batchNo)} · supplied ${b.quantity}</option>`))).join('')}</select><label class="field-label">Quantity</label><input class="field" name="quantity" type="number" min=".001" step=".001" required><label class="field-label">Reason</label><textarea class="field" name="reason" required minlength="5"></textarea></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="ph-ret-form">Submit return</button>');
  $('#ph-ret-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d=disp.data.find(x=>x._id===f.get('dispensingId')),batch=$('#ph-ret-form [name=batchId]').selectedOptions[0];if(batch.dataset.disp!==d._id)return toast('Select a batch from the selected dispensing.','error');try{await api('/pharmacy/returns',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({patientId:d.patientId._id,dispensingId:d._id,reason:f.get('reason'),items:[{batchId:f.get('batchId'),quantity:Number(f.get('quantity'))}]})});closeModal();toast('Return submitted for inspection');navigate('Returns & Supplier Payments')}catch(x){toast(x.message,'error')}};
 };
 $('#ph-supplier-return').onclick=()=>{if(!sup.data.length||!inv.data.length)return toast('Suppliers and stock batches are required.','error');showModal('Request supplier return',`<form id="ph-sret-form" class="space-y-3"><label class="field-label">Supplier</label><select class="field" name="supplierId">${sup.data.map(x=>`<option value="${x._id}">${esc(x.name)}</option>`).join('')}</select><label class="field-label">Branch</label><select class="field" name="branchId">${[...new Map(inv.data.map(x=>[String(x.branchId?._id||x.branchId),x.branchId])).values()].map(x=>`<option value="${x?._id||x}">${esc(x?.name||x)}</option>`).join('')}</select><label class="field-label">Purchase order (optional)</label><select class="field" name="purchaseOrderId"><option value="">Not linked</option>${po.data.map(x=>`<option value="${x._id}">${esc(x.orderNo)} · ${esc(x.supplierId?.name)}</option>`).join('')}</select><label class="field-label">Batch</label><select class="field" name="batchId">${inv.data.map(x=>`<option value="${x._id}">${esc(x.medicineId?.name)} · ${esc(x.batchNo)} · ${x.quantity} units</option>`).join('')}</select><label class="field-label">Quantity</label><input class="field" name="quantity" type="number" min=".001" step=".001" required><label class="field-label">Reason</label><input class="field" name="reason" required><label class="field-label">Supplier credit note reference (optional)</label><input class="field" name="supplierCreditNoteNo"></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="ph-sret-form">Submit supplier return</button>');$('#ph-sret-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),batch=inv.data.find(x=>x._id===f.get('batchId'));try{await api('/pharmacy/supplier-returns',{method:'POST',body:JSON.stringify({supplierId:f.get('supplierId'),branchId:f.get('branchId'),supplierCreditNoteNo:f.get('supplierCreditNoteNo'),purchaseOrderId:f.get('purchaseOrderId')||undefined,items:[{batchId:batch._id,quantity:Number(f.get('quantity')),reason:f.get('reason')}]})});closeModal();toast('Supplier return submitted');navigate('Returns & Supplier Payments')}catch(x){toast(x.message,'error')}}};
 $('#ph-supplier-payment').onclick=()=>{if(!sup.data.length)return toast('Create a supplier first.','error');showModal('Record supplier payment',`<form id="ph-sup-pay-form" class="space-y-3"><label class="field-label">Supplier</label><select class="field" name="supplierId">${sup.data.map(x=>`<option value="${x._id}">${esc(x.name)}</option>`).join('')}</select><label class="field-label">Purchase order (optional)</label><select class="field" name="purchaseOrderId"><option value="">General supplier payment</option>${po.data.map(x=>`<option value="${x._id}">${esc(x.orderNo)} · ${esc(x.supplierId?.name)} · ${pharmacyMoney(x.total)}</option>`).join('')}</select><label class="field-label">Branch</label><select class="field" name="branchId">${branches.data.map(b=>`<option value="${b._id}" ${state.selectedBranch===b._id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><label class="field-label">Amount</label><input class="field" name="amount" type="number" min=".01" step=".01" required><label class="field-label">Method</label><select class="field" name="method"><option value="bank_transfer">Bank transfer</option><option value="upi">UPI</option><option value="cash">Cash</option><option value="cheque">Cheque</option><option value="other">Other</option></select><label class="field-label">Reference</label><input class="field" name="reference"></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="ph-sup-pay-form">Record payment</button>');$('#ph-sup-pay-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/pharmacy/supplier-payments',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({supplierId:f.get('supplierId'),purchaseOrderId:f.get('purchaseOrderId')||undefined,branchId:f.get('branchId'),amount:Number(f.get('amount')),method:f.get('method'),reference:f.get('reference')})});closeModal();toast('Supplier payment recorded');navigate('Returns & Supplier Payments')}catch(x){toast(x.message,'error')}};
 };
 root.querySelectorAll('[data-ret-review]').forEach(b=>b.onclick=()=>{const x=ret.data.find(v=>v._id===b.dataset.retReview);const items=x.items.map(i=>`<label class="flex gap-2 items-center text-xs py-2"><input type="checkbox" data-restock="${i._id}"> Restock ${esc(i.batchId||i.medicineId)} only if unopened and suitable</label>`).join('');const note=prompt('Inspection notes (must be 5+ characters if restocking):');if(note===null)return;const restockIds=[...root.querySelectorAll(`[data-ret-review="${b.dataset.retReview}"]`)].map(()=>[]);showModal('Approve customer return',`<p class="text-xs text-muted">Choose only items verified as unopened and suitable for sale.</p>${x.items.map(i=>`<label class="flex gap-2 items-center text-xs py-2"><input type="checkbox" data-restock="${i._id}"> Restock batch ${esc(String(i.batchId).slice(-6))} · qty ${i.quantity}</label>`).join('')}<input id="ph-ret-condition" class="field" placeholder="Inspection condition / notes" value="${esc(note)}">`,'<button class="btn-secondary" data-close>Cancel</button><button id="ph-ret-approve" class="btn-primary">Approve return</button>');$('#ph-ret-approve').onclick=async()=>{const selected=[...document.querySelectorAll('[data-restock]:checked')].map(x=>({itemId:x.dataset.restock,restockable:true,condition:$('#ph-ret-condition').value}));try{await api(`/pharmacy/returns/${x._id}/review`,{method:'PATCH',body:JSON.stringify({decision:'approve',items:selected})});closeModal();toast('Return processed and eligible credit note created');navigate('Returns & Supplier Payments')}catch(e){toast(e.message,'error')}}});
 root.querySelectorAll('[data-sret-process]').forEach(b=>b.onclick=async()=>{if(!confirm('Approve supplier return and deduct available stock?'))return;const supplierCreditNoteNo=prompt('Supplier credit note reference (optional)')||'';try{await api(`/pharmacy/supplier-returns/${b.dataset.sretProcess}/process`,{method:'PATCH',body:JSON.stringify({supplierCreditNoteNo})});toast('Supplier return processed');navigate('Returns & Supplier Payments')}catch(e){toast(e.message,'error')}});
}
